/*
 * The service worker behind "Add to Home screen".
 *
 * Its whole job is that the icon opens to something. Without it, a phone off
 * the shop Wi-Fi taps the icon and gets the browser's dinosaur — which reads
 * as "the app is broken", not "you are out of range". With it, the app opens,
 * shows what it last saw (see `lib/offline.ts`) and says so.
 *
 * There is no build-time precache manifest here on purpose. The asset names
 * carry a content hash, so a hand-written list would be wrong the first time
 * anything changed and would have to be regenerated by a plugin. Instead the
 * shell is cached the first time it is fetched and served from the cache
 * afterwards while a fresh copy is pulled in the background. One visit on the
 * shop Wi-Fi is all it takes to make the icon work off it.
 *
 * `/api/` is never cached, at any point, by anything here. A stale answer to
 * "what is this customer's balance" is the one thing this app must not invent,
 * and the app's own store — which dates every figure it keeps — is where that
 * question is answered offline.
 */

const CACHE = 'pos-mobile-v1'

self.addEventListener('install', (event) => {
  // Take over as soon as this version is ready, rather than waiting for every
  // tab to close. A shop phone has one tab and never closes it.
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.add(new Request('/', { cache: 'reload' })))
      .catch(() => undefined)
      .then(() => self.skipWaiting())
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((names) =>
        Promise.all(names.filter((name) => name !== CACHE).map((name) => caches.delete(name)))
      )
      .then(() => self.clients.claim())
  )
})

self.addEventListener('fetch', (event) => {
  const request = event.request
  if (request.method !== 'GET') return

  const url = new URL(request.url)
  if (url.origin !== self.location.origin) return
  if (url.pathname.startsWith('/api/')) return

  // A navigation (opening the icon, or a reload) must always produce the app,
  // online or not.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone()
          void caches.open(CACHE).then((cache) => cache.put('/', copy))
          return response
        })
        .catch(() => caches.match('/').then((cached) => cached ?? Response.error()))
    )
    return
  }

  // Assets: serve what is cached at once, and quietly refresh it for next time.
  event.respondWith(
    caches.match(request).then((cached) => {
      const network = fetch(request)
        .then((response) => {
          if (response.ok) {
            const copy = response.clone()
            void caches.open(CACHE).then((cache) => cache.put(request, copy))
          }
          return response
        })
        .catch(() => cached ?? Response.error())

      return cached ?? network
    })
  )
})
